//! The app's read path onto the imagination feed.
//!
//! `bsc-imagine` owns the model and the on-disk format; this is the two commands the widget needs
//! and nothing else. Read-only on purpose — the app SHOWS what the ear heard, it does not draw. The
//! producer is `bsc imagine`, which runs outside the app for the same reason the transcriber does:
//! a slow or crashed renderer must never be able to stall the window.
//!
//! ## An entry id arrives from the webview, so it is not a path
//!
//! [`imagination_image`] is handed an id by the frontend and turns it into a filename. That is the
//! shape that becomes a path traversal the moment anyone relaxes it, so the id is validated against
//! a closed character set FIRST and the result is confined to the feed directory — the same
//! no-user-controlled-dispatch property the widget switch has, applied to a filesystem instead of a
//! component. `..`, a separator, or a NUL is refused rather than sanitised: silently rewriting a
//! hostile id into a valid one answers a question nobody asked.

use base64::Engine as _;

/// Where the feed lives, or an error naming why the base directory could not be resolved.
fn dir() -> Result<std::path::PathBuf, String> {
    let base = bsc_util::bsc_base_dir()
        .ok_or("no home directory, so ~/.base-studio-code could not be resolved")?;
    Ok(bsc_imagine::store::feed_dir(&base))
}

/// Whether an entry id is safe to turn into a filename.
///
/// Deliberately a whitelist. Ids are minted by the producer as timestamp-and-counter strings, so
/// this rejects everything a real id never contains.
pub fn is_safe_id(id: &str) -> bool {
    !id.is_empty()
        && id.len() <= 128
        && id.chars().all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_')
}

/// The current state of the feed: absent, empty, ready with entries, or failing with a reason.
pub fn imagination_feed() -> Result<bsc_imagine::FeedState, String> {
    let dir = dir()?;
    let now = bsc_util::now_ms();
    Ok(bsc_imagine::store::read(&dir, now, &bsc_imagine::Budget::default()))
}

/// One entry's image, as a `data:` URI.
///
/// A data URI rather than a file path because the webview cannot read the filesystem, and rather
/// than the asset protocol because that would open a whole directory to the page to deliver one
/// picture the page already has the id for. At 384² a PNG is a few hundred kilobytes and the widget
/// re-fetches only when the newest id changes.
pub fn imagination_image(id: String) -> Result<String, String> {
    if !is_safe_id(&id) {
        return Err(format!("not a valid entry id: {id:?}"));
    }
    let path = bsc_imagine::store::image_path(&dir()?, &id);
    let bytes = std::fs::read(&path).map_err(|e| format!("cannot read the image for {id}: {e}"))?;
    let b64 = base64::engine::general_purpose::STANDARD.encode(bytes);
    Ok(format!("data:image/png;base64,{b64}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_real_entry_id_is_accepted() {
        for id in ["1788617448002-001", "abc", "A1_b-2", &"x".repeat(128)] {
            assert!(is_safe_id(id), "{id:?} should be a valid id");
        }
    }

    #[test]
    fn anything_that_could_leave_the_feed_directory_is_refused() {
        // Refused, never sanitised: rewriting a hostile id into a valid one answers a question
        // nobody asked, and hides that someone asked it.
        for id in [
            "",
            "..",
            "../etc/passwd",
            "a/b",
            "a\\b",
            "/etc/passwd",
            "a.png",
            "a b",
            "a\0b",
            "café",
            &"x".repeat(129),
        ] {
            assert!(!is_safe_id(id), "{id:?} should be refused");
        }
    }

    #[test]
    fn the_image_command_refuses_a_traversing_id_before_touching_the_disk() {
        let err = imagination_image("../../etc/passwd".into()).unwrap_err();
        assert!(err.contains("not a valid entry id"), "expected a validation refusal, got: {err}");
    }
}
